def transform(grid):
    # All demonstrations leave the input unchanged except recoloring a trailing
    # background segment on a single row. This general rule chooses a row whose
    # foreground run is shorter than an otherwise full-width matching pattern.
    out = [row[:] for row in grid]
    bg = min(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # For paired motifs, detect a foreground row with a trailing background tail
    # that corresponds to the same run in the companion block, and mark tail 1.
    for r, row in enumerate(grid):
        fg = [c for c, v in enumerate(row) if v != bg]
        if not fg:
            continue
        last = max(fg)
        if last < len(row)-1:
            # Fill the row's trailing background only when a matching foreground
            # run is present in another row and extends farther right.
            for other in grid:
                other_fg = [c for c, v in enumerate(other) if v == row[fg[0]]]
                if other_fg and max(other_fg) > last:
                    for c in range(last+1, len(row)):
                        if row[c] == bg:
                            out[r][c] = 1
                    break
    return out
